import crypto from 'node:crypto';
import pool from '../db.js';
import { ApiError, isoDate } from '../utils.js';

/**
 * Central employee document read model.
 *
 * One employee record is the source of truth. Documents arrive from three
 * places and are presented as one history:
 *   1. employee_documents       — uploaded through Document Management
 *   2. onboarding_documents     — collected during onboarding (reused, not copied)
 *   3. employee_exit_documents  — generated by Offboarding (reused, not copied)
 */

export const STATUSES = ['pending', 'verified', 'rejected'];

export const ONBOARDING_CATEGORY_SLUG = {
  identity_proof: 'national-id',
  pan_card: 'pan-card',
  address_proof: 'address-proof',
  photograph: 'photograph',
  educational_certificate: 'graduation-certificate',
  previous_employment: 'experience-letter',
  bank_proof: 'bank-proof',
  signed_offer_letter: 'offer-letter',
  employment_agreement: 'employment-agreement',
  other: 'other',
};

const EXIT_CATEGORY_SLUG = {
  experience_letter: 'experience-letter',
  relieving_letter: 'relieving-letter',
  exit_confirmation: 'experience-letter',
  final_settlement: 'other',
};

export const DOCUMENT_DEFAULT_SETTINGS = {
  documents_enabled: '1',
  default_requires_verification: '1',
  max_upload_mb: '15',
  allowed_extensions: 'pdf,jpg,jpeg,png,doc,docx',
  expiry_warning_days: '30',
  expiry_reminder_days: '30,15,7,0',
  notify_employee: '1',
  notify_hr: '1',
  missing_document_reminders: '1',
  retention_years: '7',
};

export async function getDocumentSettings() {
  const [rows] = await pool.query('SELECT setting_key, setting_value FROM document_settings');
  return { ...DOCUMENT_DEFAULT_SETTINGS, ...Object.fromEntries(rows.map((r) => [r.setting_key, r.setting_value])) };
}

export const settingFlag = (value) => String(value ?? '0') === '1' || value === true;

export async function getCategoryMap() {
  const [rows] = await pool.query('SELECT * FROM document_categories ORDER BY sort_order ASC, name ASC');
  const byId = new Map();
  const bySlug = new Map();
  for (const row of rows) {
    byId.set(Number(row.id), row);
    bySlug.set(row.slug, row);
  }
  return { rows, byId, bySlug };
}

export function normalizeOnboardingStatus(status) {
  if (status === 'verified') return 'verified';
  if (status === 'rejected') return 'rejected';
  return 'pending';
}

export function expiryInfo(expiryDate, warningDays = 30) {
  if (!expiryDate) return { key: 'none', label: 'No expiry', days: null };
  const today = new Date(`${isoDate()}T00:00:00`);
  const expiry = new Date(`${String(expiryDate).slice(0, 10)}T00:00:00`);
  if (Number.isNaN(expiry.getTime())) return { key: 'none', label: 'No expiry', days: null };
  const days = Math.ceil((expiry.getTime() - today.getTime()) / 86400000);
  if (days < 0) return { key: 'expired', label: 'Expired', days };
  if (days <= Number(warningDays || 30)) return { key: 'expiring', label: 'Expiring soon', days };
  return { key: 'valid', label: 'Valid', days };
}

function categoryForOnboarding(doc, categories) {
  const slug = ONBOARDING_CATEGORY_SLUG[doc.doc_type] || 'other';
  return categories.bySlug.get(slug) || null;
}

function normalizeCanonical(row, categories) {
  const category = categories.byId.get(Number(row.category_id));
  return {
    uid: `doc-${row.id}`,
    id: Number(row.id),
    source: 'documents',
    source_label: 'Document Management',
    employee_id: Number(row.employee_id),
    employee_name: row.employee_name,
    employee_code: row.employee_code,
    avatar_color: row.avatar_color,
    department_id: row.department_id ? Number(row.department_id) : null,
    department_name: row.department_name,
    category_id: Number(row.category_id),
    category_name: row.category_name || category?.name || 'Other Document',
    category_slug: row.category_slug || category?.slug || 'other',
    category_group: row.group_name || category?.group_name || 'Other Documents',
    name: row.name,
    document_number: row.document_number,
    document_number_value: row.document_number_value,
    issue_date: row.issue_date,
    expiry_date: row.expiry_date,
    description: row.description,
    status: row.status,
    verification_notes: row.verification_notes,
    rejection_reason: row.rejection_reason,
    file_name: row.file_name,
    file_size: Number(row.file_size) || 0,
    mime_type: row.mime_type,
    storage_provider: row.storage_provider,
    storage_key: row.storage_key,
    storage_file_id: row.storage_file_id,
    file_hash: row.file_hash,
    uploaded_by: row.uploaded_by,
    uploaded_by_name: row.uploaded_by_name,
    uploaded_at: row.created_at,
    verified_by: row.verified_by,
    verified_by_name: row.verified_by_name,
    verified_at: row.verified_at,
    requires_expiry: Boolean(Number(category?.requires_expiry)),
    can_replace: true,
    can_verify: true,
    can_delete: true,
  };
}

function normalizeOnboarding(row, categories) {
  const category = categoryForOnboarding(row, categories);
  return {
    uid: `onb-${row.id}`,
    id: Number(row.id),
    source: 'onboarding',
    source_label: 'Onboarding',
    onboarding_id: Number(row.onboarding_id),
    employee_id: row.employee_id ? Number(row.employee_id) : null,
    employee_name: row.employee_name,
    employee_code: row.employee_code,
    avatar_color: row.avatar_color,
    department_id: row.department_id ? Number(row.department_id) : null,
    department_name: row.department_name,
    category_id: category ? Number(category.id) : null,
    category_name: category?.name || 'Other Document',
    category_slug: category?.slug || 'other',
    category_group: category?.group_name || 'Other Documents',
    name: row.title,
    document_number: null,
    document_number_value: null,
    issue_date: null,
    expiry_date: null,
    description: null,
    status: normalizeOnboardingStatus(row.status),
    raw_status: row.status,
    verification_notes: null,
    rejection_reason: row.rejection_reason,
    file_name: row.original_filename,
    file_size: Number(row.file_size) || 0,
    mime_type: row.mime_type,
    uploaded_at: row.uploaded_at,
    verified_by_name: row.verified_by_name,
    verified_at: row.verified_at,
    requires_expiry: false,
    can_replace: false,
    can_verify: true,
    can_delete: false,
  };
}

function normalizeExit(row, categories) {
  const slug = EXIT_CATEGORY_SLUG[row.doc_type] || 'other';
  const category = categories.bySlug.get(slug) || categories.bySlug.get('other') || null;
  return {
    uid: `ext-${row.id}`,
    id: Number(row.id),
    source: 'exit',
    source_label: 'Offboarding',
    employee_id: Number(row.employee_id),
    employee_name: row.employee_name,
    employee_code: row.employee_code,
    avatar_color: row.avatar_color,
    department_id: row.department_id ? Number(row.department_id) : null,
    department_name: row.department_name,
    category_id: category ? Number(category.id) : null,
    category_name: category?.name || 'Other Document',
    category_slug: category?.slug || 'other',
    category_group: category?.group_name || 'Other Documents',
    name: row.title,
    document_number: row.document_number,
    document_number_value: row.document_number,
    issue_date: row.generated_at ? String(row.generated_at).slice(0, 10) : null,
    expiry_date: null,
    description: null,
    status: 'verified',
    verification_notes: 'Generated by Offboarding.',
    rejection_reason: null,
    file_name: row.pdf_filename || `${row.document_number}.pdf`,
    file_size: 0,
    mime_type: 'application/pdf',
    uploaded_at: row.generated_at,
    uploaded_by_name: row.generated_by_name,
    verified_by_name: row.generated_by_name,
    verified_at: row.generated_at,
    requires_expiry: false,
    can_replace: false,
    can_verify: false,
    can_delete: false,
  };
}

function matchesCommon(doc, filters) {
  if (!doc) return false;
  if (filters.employeeId && Number(doc.employee_id) !== Number(filters.employeeId)) return false;
  if (filters.departmentId && Number(doc.department_id) !== Number(filters.departmentId)) return false;
  if (filters.categoryId && Number(doc.category_id) !== Number(filters.categoryId)) return false;
  if (filters.status && doc.status !== filters.status) return false;
  if (filters.source && doc.source !== filters.source) return false;
  if (filters.search) {
    const haystack = `${doc.name} ${doc.category_name} ${doc.employee_name || ''} ${doc.employee_code || ''} ${doc.document_number_value || ''} ${doc.document_number || ''}`.toLowerCase();
    if (!haystack.includes(String(filters.search).trim().toLowerCase())) return false;
  }
  const uploaded = String(doc.uploaded_at || '').slice(0, 10);
  if (filters.from && uploaded < String(filters.from).slice(0, 10)) return false;
  if (filters.to && uploaded > String(filters.to).slice(0, 10)) return false;
  return true;
}

const CANONICAL_BASE = `
  SELECT d.*, c.name AS category_name, c.slug AS category_slug, c.group_name,
         CONCAT(e.first_name, ' ', e.last_name) AS employee_name,
         e.employee_code, e.avatar_color,
         dpt.name AS department_name,
         u.name AS uploaded_by_name, v.name AS verified_by_name
  FROM employee_documents d
  JOIN hrm_employees e ON e.id = d.employee_id
  JOIN document_categories c ON c.id = d.category_id
  LEFT JOIN hrm_departments dpt ON dpt.id = d.department_id
  LEFT JOIN hrm_users u ON u.id = d.uploaded_by
  LEFT JOIN hrm_users v ON v.id = d.verified_by
`;

const ONBOARDING_BASE = `
  SELECT od.id, od.onboarding_id, od.doc_type, od.title, od.original_filename,
         od.file_size, od.mime_type, od.status, od.rejection_reason, od.verified_at,
         od.uploaded_at, od.file_path,
         obr.employee_id, e.employee_code, e.avatar_color,
         CONCAT(e.first_name, ' ', e.last_name) AS employee_name,
         obr.department_id, dpt.name AS department_name,
         u.name AS verified_by_name
  FROM onboarding_documents od
  JOIN onboarding_records obr ON obr.id = od.onboarding_id
  JOIN hrm_employees e ON e.id = obr.employee_id
  LEFT JOIN hrm_departments dpt ON dpt.id = obr.department_id
  LEFT JOIN hrm_users u ON u.id = od.verified_by
  WHERE obr.employee_id IS NOT NULL
`;

const EXIT_BASE = `
  SELECT eed.id, eed.employee_id, eed.doc_type, eed.document_number, eed.title,
         eed.pdf_filename, eed.generated_at, eed.generated_by,
         e.employee_code, e.avatar_color,
         CONCAT(e.first_name, ' ', e.last_name) AS employee_name,
         e.department_id, dpt.name AS department_name,
         u.name AS generated_by_name
  FROM employee_exit_documents eed
  JOIN hrm_employees e ON e.id = eed.employee_id
  LEFT JOIN hrm_departments dpt ON dpt.id = e.department_id
  LEFT JOIN hrm_users u ON u.id = eed.generated_by
`;

/**
 * Load every document visible to the caller. Employee self-service is scoped
 * to the employee's own record through `ownEmployeeId`.
 */
export async function listAllDocuments(req, filters = {}, { ownEmployeeId = null, categories } = {}) {
  const cat = categories || (await getCategoryMap());
  const settings = await getDocumentSettings();
  const warningDays = Number(settings.expiry_warning_days) || 30;

  const params = [];
  const where = [];
  if (ownEmployeeId) {
    where.push('d.employee_id = ?');
    params.push(ownEmployeeId);
  }
  if (filters.employeeId && !ownEmployeeId) {
    where.push('d.employee_id = ?');
    params.push(Number(filters.employeeId));
  }
  if (filters.departmentId && !ownEmployeeId) {
    where.push('d.department_id = ?');
    params.push(Number(filters.departmentId));
  }
  if (filters.categoryId) {
    where.push('d.category_id = ?');
    params.push(Number(filters.categoryId));
  }
  if (filters.status) {
    where.push('d.status = ?');
    params.push(filters.status);
  }
  if (filters.search) {
    const q = `%${String(filters.search).trim()}%`;
    where.push(`(d.name LIKE ? OR d.document_number LIKE ? OR d.document_number_value LIKE ? OR e.first_name LIKE ? OR e.last_name LIKE ? OR e.employee_code LIKE ? OR CONCAT(e.first_name,' ',e.last_name) LIKE ?)`);
    params.push(q, q, q, q, q, q, q);
  }
  if (filters.from) {
    where.push('DATE(d.created_at) >= ?');
    params.push(String(filters.from).slice(0, 10));
  }
  if (filters.to) {
    where.push('DATE(d.created_at) <= ?');
    params.push(String(filters.to).slice(0, 10));
  }
  const clause = where.length ? `WHERE ${where.join(' AND ')}` : '';

  const [canonicalRows] = await pool.query(`${CANONICAL_BASE} ${clause}`, params);
  const includeCanonical = !filters.source || filters.source === 'documents' || filters.source === 'upload';
  const documents = includeCanonical ? canonicalRows.map((row) => normalizeCanonical(row, cat)) : [];

  // Onboarding and exit documents are optional sources in the merged view.
  if (!filters.source || filters.source === 'onboarding') {
    const onbParams = [];
    const onbWhere = [];
    if (ownEmployeeId) {
      onbWhere.push('obr.employee_id = ?');
      onbParams.push(ownEmployeeId);
    }
    if (filters.employeeId && !ownEmployeeId) {
      onbWhere.push('obr.employee_id = ?');
      onbParams.push(Number(filters.employeeId));
    }
    if (filters.departmentId && !ownEmployeeId) {
      onbWhere.push('obr.department_id = ?');
      onbParams.push(Number(filters.departmentId));
    }
    const onbClause = onbWhere.length ? ` AND ${onbWhere.join(' AND ')}` : '';
    const [onbRows] = await pool.query(
      `${ONBOARDING_BASE}${onbClause} ORDER BY od.uploaded_at DESC LIMIT 500`,
      onbParams
    );
    for (const row of onbRows) {
      const doc = normalizeOnboarding(row, cat);
      if (matchesCommon(doc, filters)) documents.push(doc);
    }
  }

  if (!filters.source || filters.source === 'exit') {
    const exitParams = [];
    const exitWhere = [];
    if (ownEmployeeId) {
      exitWhere.push('eed.employee_id = ?');
      exitParams.push(ownEmployeeId);
    }
    if (filters.employeeId && !ownEmployeeId) {
      exitWhere.push('eed.employee_id = ?');
      exitParams.push(Number(filters.employeeId));
    }
    if (filters.departmentId && !ownEmployeeId) {
      exitWhere.push('e.department_id = ?');
      exitParams.push(Number(filters.departmentId));
    }
    const exitClause = exitWhere.length ? ` WHERE ${exitWhere.join(' AND ')}` : '';
    const [exitRows] = await pool.query(
      `${EXIT_BASE}${exitClause} ORDER BY eed.generated_at DESC LIMIT 500`,
      exitParams
    );
    for (const row of exitRows) {
      const doc = normalizeExit(row, cat);
      if (matchesCommon(doc, filters)) documents.push(doc);
    }
  }

  for (const doc of documents) {
    const info = expiryInfo(doc.expiry_date, warningDays);
    doc.expiry_status = info.key;
    doc.expiry_label = info.label;
    doc.days_remaining = info.days;
  }

  const expiryFilter = filters.expiryStatus || filters.expiry;
  let result = documents;
  if (expiryFilter) {
    result = result.filter((doc) => {
      if (expiryFilter === 'expiring_soon') return doc.expiry_status === 'expiring';
      if (expiryFilter === 'expired') return doc.expiry_status === 'expired';
      if (expiryFilter === 'valid') return doc.expiry_status === 'valid';
      if (expiryFilter === 'no_expiry') return doc.expiry_status === 'none';
      return true;
    });
  }
  if (filters.days) {
    const days = Number(filters.days);
    result = result.filter(
      (doc) => doc.expiry_date && doc.days_remaining != null && doc.days_remaining >= 0 && doc.days_remaining <= days
    );
  }

  const sort = filters.sort || 'newest';
  const sorted = [...result].sort((a, b) => {
    if (sort === 'oldest') return String(a.uploaded_at).localeCompare(String(b.uploaded_at));
    if (sort === 'name') return String(a.name).localeCompare(String(b.name));
    if (sort === 'expiry') {
      if (!a.expiry_date) return 1;
      if (!b.expiry_date) return -1;
      return String(a.expiry_date).localeCompare(String(b.expiry_date));
    }
    return String(b.uploaded_at).localeCompare(String(a.uploaded_at));
  });

  return sorted;
}

export function paginate(rows, query = {}) {
  const page = Math.max(1, Number(query.page) || 1);
  const limit = Math.min(100, Math.max(1, Number(query.limit) || 15));
  const total = rows.length;
  const start = (page - 1) * limit;
  return {
    data: rows.slice(start, start + limit),
    pagination: { page, limit, total, pages: Math.ceil(total / limit) || 1 },
  };
}

export function canViewDocument(req, doc) {
  if (req.user.role === 'super_admin') return true;
  if (doc.employee_id && Number(doc.employee_id) === Number(req.user.employeeId)) return true;
  return req.permissions.includes('documents.view');
}

export async function loadDocumentByIdentity(req, identity, categories) {
  const raw = String(identity || '');
  const cat = categories || (await getCategoryMap());
  const settings = await getDocumentSettings();
  const warningDays = Number(settings.expiry_warning_days) || 30;

  if (raw.startsWith('onb-')) {
    const id = Number(raw.slice(4));
    const [rows] = await pool.query(`${ONBOARDING_BASE} AND od.id = ? LIMIT 1`, [id]);
    if (!rows[0]) return null;
    const doc = normalizeOnboarding(rows[0], cat);
    const info = expiryInfo(doc.expiry_date, warningDays);
    return { ...doc, expiry_status: info.key, expiry_label: info.label, days_remaining: info.days };
  }
  if (raw.startsWith('ext-')) {
    const id = Number(raw.slice(4));
    const [rows] = await pool.query(`${EXIT_BASE} WHERE eed.id = ? LIMIT 1`, [id]);
    if (!rows[0]) return null;
    const doc = normalizeExit(rows[0], cat);
    return { ...doc, expiry_status: 'none', expiry_label: 'No expiry', days_remaining: null };
  }

  const id = Number(raw.replace(/^doc-/, ''));
  if (!Number.isInteger(id) || id <= 0) return null;
  const [rows] = await pool.query(`${CANONICAL_BASE} WHERE d.id = ? LIMIT 1`, [id]);
  if (!rows[0]) return null;
  const doc = normalizeCanonical(rows[0], cat);
  const info = expiryInfo(doc.expiry_date, warningDays);
  return { ...doc, expiry_status: info.key, expiry_label: info.label, days_remaining: info.days };
}

export async function logActivity(conn, { documentId = null, employeeId = null, action, details = null, userId = null }) {
  await conn.query(
    `INSERT INTO document_activity_history (document_id, employee_id, action, details, performed_by)
     VALUES (?,?,?,?,?)`,
    [documentId, employeeId, action, details ? JSON.stringify(details) : null, userId]
  );
}

export async function logVerification(conn, { documentId, action, status, notes = null, rejectionReason = null, userId = null }) {
  await conn.query(
    `INSERT INTO document_verification_history
       (document_id, action, status, notes, rejection_reason, performed_by)
     VALUES (?,?,?,?,?,?)`,
    [documentId, action, status || null, notes, rejectionReason, userId]
  );
}

export async function nextDocumentNumber(conn = pool) {
  const year = new Date().getFullYear();
  const prefix = `DOC-${year}-`;
  const [[row]] = await conn.query(
    `SELECT COALESCE(MAX(CAST(SUBSTRING(document_number, ?) AS UNSIGNED)), 0) AS maxCode
     FROM employee_documents WHERE document_number LIKE ?`,
    [prefix.length + 1, `${prefix}%`]
  );
  return `${prefix}${String(Number(row.maxCode) + 1).padStart(4, '0')}`;
}

export async function getEmployee(employeeId) {
  const [[row]] = await pool.query(
    `SELECT e.id, e.first_name, e.last_name, e.employee_code, e.department_id, e.status,
            CONCAT(e.first_name, ' ', e.last_name) AS name
     FROM hrm_employees e WHERE e.id = ? LIMIT 1`,
    [employeeId]
  );
  return row || null;
}

/**
 * Missing / completeness model for required document categories.
 * Existing onboarding documents are mapped to the same category catalogue,
 * so HR is never asked to collect a document twice.
 */
export async function computeMissingDocuments({ ownEmployeeId = null, documents = null, categories = null } = {}) {
  const cat = categories || (await getCategoryMap());
  const required = cat.rows.filter((c) => Number(c.is_required) && Number(c.is_active));
  const docs = documents || (await listAllDocuments({ user: {}, permissions: [] }, {}, { ownEmployeeId }));

  const employeeParams = [];
  let employeeWhere = "WHERE e.status <> 'inactive'";
  if (ownEmployeeId) {
    employeeWhere = 'WHERE e.id = ?';
    employeeParams.push(ownEmployeeId);
  }
  const [employees] = await pool.query(
    `SELECT e.id, e.employee_code, CONCAT(e.first_name, ' ', e.last_name) AS employee_name,
            e.avatar_color, e.department_id, d.name AS department_name
     FROM hrm_employees e LEFT JOIN hrm_departments d ON d.id = e.department_id
     ${employeeWhere} ORDER BY e.first_name, e.last_name`,
    employeeParams
  );

  const [reminders] = await pool.query(
    `SELECT employee_id, category_id, MAX(sent_at) AS last_reminder
     FROM document_reminder_history
     WHERE reminder_type IN ('missing','missing_document')
     GROUP BY employee_id, category_id`
  );
  const reminderMap = new Map(
    reminders.map((r) => [`${r.employee_id}:${r.category_id}`, r.last_reminder])
  );

  const byEmployeeCategory = new Map();
  for (const doc of docs) {
    if (!doc.category_id) continue;
    const key = `${doc.employee_id}:${doc.category_id}`;
    const current = byEmployeeCategory.get(key);
    const rank = { verified: 3, pending: 2, rejected: 1 };
    if (!current || (rank[doc.status] || 0) > (rank[current.status] || 0)) {
      byEmployeeCategory.set(key, doc);
    }
  }

  const rows = [];
  const complete = new Map();
  for (const emp of employees) {
    let verifiedAll = true;
    for (const category of required) {
      const doc = byEmployeeCategory.get(`${emp.id}:${category.id}`) || null;
      const exp = doc ? expiryInfo(doc.expiry_date) : null;
      const status = doc
        ? exp?.key === 'expired'
          ? 'expired'
          : doc.status
        : 'missing';
      if (status !== 'verified') verifiedAll = false;
      rows.push({
        employee_id: emp.id,
        employee_name: emp.employee_name,
        employee_code: emp.employee_code,
        avatar_color: emp.avatar_color,
        department_id: emp.department_id,
        department_name: emp.department_name,
        category_id: category.id,
        category_name: category.name,
        category_group: category.group_name,
        document_uid: doc?.uid || null,
        document_id: doc?.id || null,
        source: doc?.source || null,
        file_name: doc?.file_name || null,
        expiry_date: doc?.expiry_date || null,
        status,
        last_reminder: reminderMap.get(`${emp.id}:${category.id}`) || null,
      });
    }
    complete.set(emp.id, verifiedAll);
  }

  return {
    required,
    employees,
    rows,
    complete,
    completeCount: [...complete.values()].filter(Boolean).length,
    incompleteCount: [...complete.values()].filter((v) => !v).length,
  };
}

export function csvEscape(value) {
  const s = value == null ? '' : String(value);
  return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

export function toCsv(headers, rows) {
  return [headers.map(csvEscape).join(','), ...rows.map((row) => row.map(csvEscape).join(','))].join('\r\n');
}

export function documentHash(buffer) {
  return crypto.createHash('sha256').update(buffer).digest('hex');
}

export function assertDocumentEnabled(settings) {
  if (!settingFlag(settings.documents_enabled)) {
    throw new ApiError(403, 'Document management is currently disabled.');
  }
}
